def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'
    last_me, last_op = history[-1]
    if n >= 2:
        prev_me, prev_op = history[-2]
        if prev_op == 'D' and last_op == 'C' and last_me == 'D':
            return 'C'
    if n == 1:
        return 'C'
    if last_op == 'D':
        if n >= 3:
            me2, op2 = history[-3]
            if op2 == 'D' and me2 == 'D':
                return 'D'
            if rng.random() < 0.55:
                return 'D'
            return 'C'
        return 'C'
    if last_op == 'C':
        if n >= 3:
            count_d = 0
            for x in history[-12:]:
                if x[1] == 'D':
                    count_d += 1
            if count_d >= 4:
                return 'D'
        return 'C'
    return 'C'

